const _globRegexCache = new Map();

function globToRegex(pattern) {
  if (typeof pattern !== 'string') return /(?!)/;
  let regex = '^';
  for (let i = 0; i < pattern.length; i += 1) {
    const c = pattern[i];
    if (c === '*' && pattern[i + 1] === '*') {
      i += 1;
      if (pattern[i + 1] === '/') {
        regex += '(?:.*/)?';
        i += 1;
      }
      else {
        regex += '.*';
      }
    }
    else if (c === '*') {
      regex += '[^/]*';
    }
    else if (c === '?') {
      regex += '[^/]';
    }
    else {
      regex += c.replace(/[.+^${}()|[\]\\]/g, '\\$&');
    }
  }
  regex += '$';
  try {
    return new RegExp(regex);
  }
  catch {
    return /(?!)/;
  }
}

